mapper.select:
select p.*, ps.script_type, ps.script_url from mp_situation_probe p left join mp_situation_probe_script ps on p.id = ps.probe_id
AND p.id in
#{pid}
AND p.probe_category in
#{category}
AND p.type in
#{type}
AND ps.script_type in
#{scriptType}
AND p.name like CONCAT('%', #{condition.name}, '%')
AND
p.OS_type like CONCAT('%', #{osType}, '%')
